- name: Create pull request if there are changes
  uses: peter-evans/create-pull-request@22a9089034f40e5a961c8808d113e2c98fb63676 # v7.0.11
  id: create_pr
  with:
    commit-message: ${{ steps.create_commit_message.outputs.commit_message }}
    branch: update-flutter-dependencies/${{ env.FLUTTER_VERSION }}
    sign-commits: true
    title: ${{ steps.create_commit_message.outputs.commit_message }}
    body: ${{ steps.pr_body.outputs.body }}
    token: ${{ steps.app-token.outputs.token }}

# Enabling auto-merge here is NOT merging on green: the main ruleset sets
# require_code_owner_review, so an App-authored PR cannot merge until the
# code owner approves. What this does is make that approval the merge —
# instead of an approval followed by a separate click.
#
# The branch update comes first. Required checks are strict, so a branch
# behind main cannot merge even when approved and green, and GitHub's
# auto-merge never updates the branch itself — it just waits, silently.
# It must happen before review: dismiss_stale_reviews_on_push means an
# update that follows an approval dismisses it.
#
# Both calls are best-effort. A PR that exists without auto-merge is a
# working outcome (the maintainer merges by hand, as before); a failed
# workflow run is not.
- name: Enable auto-merge on the pull request
  if: steps.create_pr.outputs.pull-request-number != ''
  uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
  env:
    PR_NUMBER: ${{ steps.create_pr.outputs.pull-request-number }}
  with:
    github-token: ${{ steps.app-token.outputs.token }}
    script: |
      const number = Number(process.env.PR_NUMBER)
      const { data: pr } = await github.rest.pulls.get({ ...context.repo, pull_number: number })

      // base.sha records the commit the PR was opened against and does not
      // advance as main does, so ask GitHub how far behind the head is.
      const { data: comparison } = await github.rest.repos.compareCommitsWithBasehead({
        ...context.repo,
        basehead: `${pr.base.ref}...${pr.head.sha}`,
      })
      if (comparison.behind_by > 0) {
        try {
          await github.rest.pulls.updateBranch({ ...context.repo, pull_number: number })
          core.info(`Updated #${number}: it was ${comparison.behind_by} commit(s) behind ${pr.base.ref}.`)
        } catch (error) {
          core.warning(`Could not update #${number} from ${pr.base.ref}: ${error.message}`)
        }
      }

      // updateBranch is asynchronous, and auto-merge waits for whatever
      // state the branch settles into, so this does not depend on it.
      try {
        await github.graphql(
          `mutation($id: ID!) {
             enablePullRequestAutoMerge(input: { pullRequestId: $id, mergeMethod: SQUASH }) {
               clientMutationId
             }
           }`,
          { id: pr.node_id },
        )
        core.info(`Auto-merge enabled on #${number}; it will merge once the code owner approves.`)
      } catch (error) {
        core.warning(`Could not enable auto-merge on #${number}: ${error.message}`)
      }

